// Generates a lean, auto-generated `{Name}.mdx` doc page next to every
// copy-paste template component (src/stories/templates/{Name}.tsx), so its
// real source shows up verbatim in both the Storybook UI and MCP's
// `docs-show` output (which returns MDX docs pages as raw file text,
// unlike CSF stories, whose `render()` gets reconstructed into synthesized
// "usage code" — see /memories/repo/storybook-vite-migration.md).
//
// `{Name}.tsx` is the single source of truth; `{Name}.mdx` is a generated
// build artifact (gitignored — see .gitignore) that must never be
// hand-edited. It's regenerated:
//   - once via `storybook:prepare` during `dev`/`build` (see package.json)
//   - live, on every save, by a Vite dev-server watcher (see .storybook/main.ts)
//   - on demand: `npm run docs:templates`
//
// Usage: node scripts/generate-template-docs.mjs
import * as fs from 'node:fs';
import * as path from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const templatesDir = path.resolve(__dirname, '../src/stories/templates');
const generatedHeader = '{/* AUTO-GENERATED by scripts/generate-template-docs.mjs';

/** Longest run of backticks in `src`, so the fence always "wins" and can't be closed early. */
function fenceFor(src) {
  const runs = src.match(/`+/g) ?? [];
  const longest = runs.reduce((max, r) => Math.max(max, r.length), 0);
  return '`'.repeat(Math.max(3, longest + 1));
}

/**
 * The sidebar `title` a docs page must use to attach to the same sidebar
 * node as `{name}.stories.tsx` (e.g. "Templates/Empty State") — read from the
 * sibling stories file's `meta.title` rather than guessed from the filename,
 * so it can never drift out of sync with the stories file's own title.
 */
function titleFor(file) {
  const name = path.basename(file, '.tsx');
  const storiesPath = path.join(path.dirname(file), `${name}.stories.tsx`);
  if (fs.existsSync(storiesPath)) {
    const source = fs.readFileSync(storiesPath, 'utf8');
    const match = source.match(/title:\s*['"]([^'"]+)['"]/);
    if (match) return match[1];
  }
  const relativeDir = path.relative(templatesDir, path.dirname(file));
  const titleSegments = relativeDir ? relativeDir.split(path.sep) : [];
  return ['Templates', ...titleSegments, name]
    .map((segment) =>
      segment
        .replace(/[-_]+/g, ' ')
        .replace(/([a-z0-9])([A-Z])/g, '$1 $2')
        .replace(/\b\w/g, (character) => character.toUpperCase()),
    )
    .join('/');
}

function mdxFor(file, source) {
  const name = path.basename(file, '.tsx');
  const fence = fenceFor(source);
  const title = titleFor(file);
  return `{/* AUTO-GENERATED by scripts/generate-template-docs.mjs — do not edit by hand.
   Source of truth: ${name}.tsx. Regenerated on dev/build start and on save. */}
import { Meta } from '@storybook/addon-docs/blocks';

<Meta title="${title}" name="Source Code" summary="Copy-pasteable ${name}.tsx" />

# ${name}.tsx

This component is not exported from the package. 
It is a copy-pasteable starter template for use in your own code.

${fence}tsx
${source}
${fence}
`;
}

function templateFiles(directory) {
  return fs.readdirSync(directory, { withFileTypes: true }).flatMap((entry) => {
    const file = path.join(directory, entry.name);
    if (entry.isDirectory()) return templateFiles(file);
    return entry.name.endsWith('.tsx') && !entry.name.endsWith('.stories.tsx') ? [file] : [];
  });
}

function removeOrphanedDocs(directory) {
  for (const entry of fs.readdirSync(directory, { withFileTypes: true })) {
    const file = path.join(directory, entry.name);
    if (entry.isDirectory()) {
      removeOrphanedDocs(file);
    } else if (
      entry.name.endsWith('.mdx') &&
      !fs.existsSync(file.replace(/\.mdx$/, '.tsx')) &&
      fs.readFileSync(file, 'utf8').startsWith(generatedHeader)
    ) {
      fs.rmSync(file);
    }
  }
}

/**
 * Regenerate the `.mdx` doc for one template component file (e.g. the
 * absolute path to `EmptyState.tsx`), or every template if no path is given.
 * Returns the list of `.mdx` file paths written.
 */
export function generateTemplateDocs(tsxPath) {
  if (!tsxPath) removeOrphanedDocs(templatesDir);
  const targets = tsxPath ? [tsxPath] : templateFiles(templatesDir);

  const written = [];
  for (const file of targets) {
    const source = fs.readFileSync(file, 'utf8');
    const mdxPath = file.replace(/\.tsx$/, '.mdx');
    fs.writeFileSync(mdxPath, mdxFor(file, source));
    written.push(mdxPath);
  }
  return written;
}

const isMain = process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href;
if (isMain) {
  const written = generateTemplateDocs();
  for (const f of written) {
    console.log(`generated ${path.relative(process.cwd(), f)}`);
  }
}
